{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher general cap, supported by the diligence record and risk allocation."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek a lower de minimis, with related claims aggregated, and a **tipping basket**"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Use claim-specific periods: longer periods for tax, title and other enduring risks"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Carve out title and capacity from the general cap and short survival period, with robust warranties and appropriate recovery."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve specific indemnities, price adjustment and completion rights, fraud, and any agreed carve-outs."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Do not let generic data-room or public-register wording qualify every warranty."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the constructive-knowledge/data-room/public-record limb."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make receipt of valid, unconditional consent **and satisfaction of all associated conditions** a completion condition, with the required form and evidence."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment and effective discharge/release of the facility and security at or before Completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Reconcile the bonuses and on-costs expressly in the completion accounts/funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Strengthen the indemnity to cover loss of rights, infringement or third-party claims and associated remediation costs"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for losses, response costs and liabilities arising from the incident, plus appropriate warranty and disclosure protections."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Confirm accrued or committed amounts are treated consistently with the debt-free/cash-free mechanics and are not left as an undisclosed post-completion liability."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the blanket application of caps, time bars, exclusive remedy and non-reliance terms to all Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Obtain appropriate title warranties and transfer evidence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Consider specific tax and IP protections, especially where exposure is identified or could outlast general warranty periods."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

